                    labels: labels,
                    datasets: [
                        { data: ds.throughputHistory.map(function(v) { return Math.round(v / 1000); }) },
                        { data: ds.dwellHistory }
                    ]
                },
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: (ds.revenueHistory || []).map(function(v) { return Math.round(v); }) },
                        { data: ds.profitHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.results || {};
            var finalThroughput = ds.throughput || 800000;
            var finalDwell = ds.dwellTime || 11;
            var finalTurnaround = ds.turnaroundTime || 4;
            var totalProfit = 0;
            for (var i = 0; i < history.length; i++) {
                totalProfit += (history[i].results && history[i].results.profit) || 0;
            }
            var finalMarketShare = ds.marketShare || 12;
            var finalSatisfaction = ds.satisfaction || 60;
            var finalSustain = ds.sustainabilityScore || 0;

            // Weights (v1.1.0): throughput 25, efficiency 25, financial 20, share 15, sustainability 15 = 100.
            // Previously sustainability was a hardcoded flat 5, so Round 3's entire theme (green
            // infrastructure, climate resilience) had NO effect on the final score. It now reads
            // the actual sustainabilityScore the player built. Financial denominator raised to 480
            // to match the recalibrated (higher) revenue base so it still discriminates. (v1.1.0)
            var throughputScore = Math.min(1, finalThroughput / 1200000) * 25;
            var efficiencyScore = Math.min(1, (11 - finalDwell) / 6 * 0.5 + (4 - finalTurnaround) / 2.8 * 0.5) * 25;
            var financialScore = Math.min(1, totalProfit / 480) * 20;
            var shareScore = Math.min(1, finalMarketShare / 20) * 15;
            var sustainScore = Math.min(1, finalSustain / 100) * 15;
            var total = Math.round(throughputScore + efficiencyScore + financialScore + shareScore + sustainScore);

            var performance = window.mySimulation.t('perf_developing_port');
            if (total >= 80) performance = window.mySimulation.t('perf_world_class');
            else if (total >= 65) performance = window.mySimulation.t('perf_competitive_hub');
            else if (total >= 50) performance = window.mySimulation.t('perf_improving_port');

            var insights = [];
            if (finalDwell <= 5) insights.push(window.mySimulation.t('insight_dwell_excellent'));
            else if (finalDwell <= 7) insights.push(window.mySimulation.t('insight_dwell_good'));
            else insights.push(window.mySimulation.t('insight_dwell_high'));

            if (totalProfit > 300) insights.push(window.mySimulation.t('insight_profit_strong'));
            else if (totalProfit > 200) insights.push(window.mySimulation.t('insight_profit_solid'));
            else insights.push(window.mySimulation.t('insight_profit_strained'));

            if (finalMarketShare > 16) insights.push(window.mySimulation.t('insight_share_gain'));
            else insights.push(window.mySimulation.t('insight_share_modest'));

            if (finalSustain >= 60) insights.push(window.mySimulation.t('insight_sustain_strong'));
            else if (finalSustain >= 30) insights.push(window.mySimulation.t('insight_sustain_some'));
            else insights.push(window.mySimulation.t('insight_sustain_neglected'));

            return {
                totalScore: total,
                throughputFinal: finalThroughput,
                dwellTimeFinal: finalDwell,
                totalProfit: totalProfit,
                marketShareFinal: finalMarketShare,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.profit < 50) return window.mySimulation.t('hint_low_profit');
            if (results.dwellTime > 8) return window.mySimulation.t('hint_high_dwell');
            if (results.satisfaction < 50) return window.mySimulation.t('hint_low_satisfaction');
            if (results.marketShare < 10) return window.mySimulation.t('hint_losing_share');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.throughput', label: 'Throughput (TEU)', i18nKey: 'col_throughput', formatter: function(v) { return Math.round(v).toLocaleString(); } },
                { key: 'results.dwellTime', label: 'Dwell (Days)', i18nKey: 'col_dwell', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.revenue', label: 'Revenue ($M)', i18nKey: 'col_revenue', formatter: function(v) { return '$' + Math.round(v); } },
                { key: 'results.profit', label: 'Profit ($M)', i18nKey: 'col_profit', formatter: function(v) { return '$' + Math.round(v); } },
                { key: 'results.marketShare', label: 'Market Share', i18nKey: 'col_marketshare', formatter: function(v) { return v.toFixed(1) + '%'; } },
                { key: 'results.capitalSpent', label: 'Capex ($M)', i18nKey: 'col_capex', formatter: function(v) { return '$' + Math.round(v); } }
            ];
        }

